function slugify(text){return text.replace(/\s+/g,'-').replace(/[^\w-]/g,'');}
document.querySelectorAll('#content h2, #content h4, #content h5').forEach(function(h){h.id=slugify(h.textContent);});var toc=document.getElementById('toc');if(toc){document.querySelectorAll('#content h2').forEach(function(h){var li=document.createElement('li');li.innerHTML='<a href="#'+h.id+'">'+h.textContent+'</a>';toc.appendChild(li);});}
function getVisited(){try{return JSON.parse(localStorage.getItem('rstat_visited')||'{}');}catch(e){return{};}}
function saveVisited(v){try{localStorage.setItem('rstat_visited',JSON.stringify(v));}catch(e){}}
function getCollapsed(){try{return JSON.parse(localStorage.getItem('rstat_subsec_collapsed')||'{}');}catch(e){return{};}}
function saveCollapsed(c){try{localStorage.setItem('rstat_subsec_collapsed',JSON.stringify(c));}catch(e){}}
function getStarted(){try{return JSON.parse(localStorage.getItem('rstat_started')||'{}');}catch(e){return{};}}
function saveStarted(s){try{localStorage.setItem('rstat_started',JSON.stringify(s));}catch(e){}}
(function(){var page=window.location.pathname.split('/').pop()||'index.html';if(!page)return;var visited=getVisited();var started=getStarted();if(!visited[page]){started[page]=true;saveStarted(started);}
try{var priorRaw=localStorage.getItem('rstat_last_visited');if(priorRaw){var prior=JSON.parse(priorRaw);if(prior&&prior.href&&prior.href!==page){localStorage.setItem('rstat_continue',priorRaw);}}
var title=document.title.replace(/\s*[\|—\-].*$/,'').trim()||page;localStorage.setItem('rstat_last_visited',JSON.stringify({href:page,title:title,ts:Date.now()}));}catch(e){}
if(visited[page])return;function markVisited(){var v=getVisited();if(v[page])return;v[page]=true;saveVisited(v);var s=getStarted();if(s[page]){delete s[page];saveStarted(s);}}
function checkDepth(){var doc=document.documentElement;var scrolled=window.scrollY||window.pageYOffset||0;var viewport=window.innerHeight||doc.clientHeight;var total=doc.scrollHeight-viewport;if(total<=0||scrolled/total>=0.8){markVisited();window.removeEventListener('scroll',onScroll);}}
var ticking=false;function onScroll(){if(ticking)return;ticking=true;requestAnimationFrame(function(){ticking=false;checkDepth();});}
window.addEventListener('scroll',onScroll,{passive:true});setTimeout(checkDepth,100);})();(function(){var sidebarEl=document.getElementById('sidebar-nav');if(!sidebarEl)return;var visited=getVisited();var started=getStarted();var collapsed=getCollapsed();var currentPage=window.location.pathname.split('/').pop()||'index.html';sidebarEl.querySelectorAll('.sidebar-section-items a').forEach(function(a){var href=a.getAttribute('href');if(!href)return;var dot=a.querySelector('.progress-dot');if(!dot)return;if(visited[href])dot.classList.add('visited');else if(started[href])dot.classList.add('started');});sidebarEl.querySelectorAll('.sidebar-section').forEach(function(section){var meta=section.querySelector('[data-section-meta]');if(!meta)return;var links=section.querySelectorAll('.sidebar-section-items > li:not(.sidebar-divider) > a');var total=links.length;if(!total)return;var done=0;links.forEach(function(a){var href=a.getAttribute('href');if(!href)return;if(visited[href]||started[href]||href===currentPage)done++;});if(done>0)meta.textContent=done+' / '+total;});(function(){var chip=sidebarEl.querySelector('[data-continue-chip]');if(!chip)return;var raw;try{raw=localStorage.getItem('rstat_continue');}catch(e){return;}
if(!raw)return;try{var lv=JSON.parse(raw);if(!lv||!lv.href||lv.href===currentPage)return;var link=chip.querySelector('[data-continue-link]');if(!link)return;link.href=lv.href;link.textContent=lv.title||lv.href;chip.classList.add('has-link');}catch(e){}})();sidebarEl.querySelectorAll('.sidebar-subsection-toggle').forEach(function(divider){var key=divider.getAttribute('data-subkey');if(collapsed[key]===true){divider.setAttribute('data-collapsed','true');var chev=divider.querySelector('.subsec-chevron');if(chev)chev.innerHTML='&#9654;';sidebarEl.querySelectorAll('li[data-subkey="'+key+'"]:not(.sidebar-subsection-toggle)').forEach(function(li){li.style.display='none';});}});sidebarEl.querySelectorAll('.sidebar-section-header').forEach(function(header){header.addEventListener('click',function(){this.closest('.sidebar-section').classList.toggle('expanded');});});sidebarEl.querySelectorAll('.sidebar-subsection-toggle').forEach(function(divider){divider.addEventListener('click',function(){var key=divider.getAttribute('data-subkey');var nowCollapsed=divider.getAttribute('data-collapsed')!=='true';divider.setAttribute('data-collapsed',nowCollapsed);var chev=divider.querySelector('.subsec-chevron');if(chev)chev.innerHTML=nowCollapsed?'&#9654;':'&#9660;';var c=getCollapsed();c[key]=nowCollapsed;saveCollapsed(c);sidebarEl.querySelectorAll('li[data-subkey="'+key+'"]:not(.sidebar-subsection-toggle)').forEach(function(li){li.style.display=nowCollapsed?'none':'';});});});})();(function(){if(!('IntersectionObserver'in window))return;var headings=document.querySelectorAll('#content h2');var tocLinks=document.querySelectorAll('#toc a');if(!headings.length||!tocLinks.length)return;var linkById={};tocLinks.forEach(function(a){var href=a.getAttribute('href')||'';if(href.charAt(0)==='#')linkById[href.slice(1)]=a;});var visibleIds={};var activeId=null;function updateActive(){var chosen=null;for(var i=0;i<headings.length;i++){if(visibleIds[headings[i].id]){chosen=headings[i].id;break;}}
if(!chosen)return;if(chosen===activeId)return;if(activeId&&linkById[activeId])linkById[activeId].classList.remove('toc-active');if(linkById[chosen])linkById[chosen].classList.add('toc-active');activeId=chosen;}
var io=new IntersectionObserver(function(entries){for(var i=0;i<entries.length;i++){visibleIds[entries[i].target.id]=entries[i].isIntersecting;}
updateActive();},{rootMargin:'-80px 0px -70% 0px',threshold:0});headings.forEach(function(h){io.observe(h);});})();